import "./navbar.css";

import {
  cloneElement,
  isValidElement,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Button } from "./button";
import { cx } from "./cx";

export type NavbarProps = ComponentProps<"nav">;

export function Navbar({ className, ...rest }: NavbarProps) {
  return <nav className={cx("ns-navbar", className)} {...rest} />;
}

type BrandLink = ComponentProps<"a"> & { href: string };
type BrandText = Omit<ComponentProps<"span">, "href"> & { href?: undefined };

export type NavbarBrandProps = BrandLink | BrandText;

export function NavbarBrand({ className, children, ...rest }: NavbarBrandProps) {
  const classNames = cx("ns-navbar__brand", className);
  const href = "href" in rest ? rest.href : undefined;

  if (href) {
    return (
      <a className={classNames} {...(rest as BrandLink)}>
        {children}
      </a>
    );
  }

  if (isValidElement<{ className?: string | undefined }>(children)) {
    return cloneElement(children, {
      className: cx(classNames, children.props.className),
    });
  }

  return (
    <span className={classNames} {...(rest as BrandText)}>
      {children}
    </span>
  );
}

export type NavbarMenuProps = ComponentProps<"details"> & {
  label?: ReactNode;
};

export function NavbarMenu({
  label = "Menu",
  className,
  children,
  ...rest
}: NavbarMenuProps) {
  return (
    <details className={cx("ns-navbar__menu", className)} {...rest}>
      <summary className="ns-button ns-navbar__toggle" data-variant="ghost">
        {label}
      </summary>
      {children}
    </details>
  );
}

export type NavbarListProps = ComponentProps<"ul">;

export function NavbarList({ className, ...rest }: NavbarListProps) {
  return <ul className={cx("ns-navbar__list", className)} {...rest} />;
}

export type NavbarItemProps = {
  children?: ReactNode;
  className?: string | undefined;
  href?: string | undefined;
  current?: boolean | undefined;
};

type LinkChild = {
  className?: string | undefined;
  "aria-current"?: "page" | undefined;
  "data-variant"?: string | undefined;
};

export function NavbarItem({
  href,
  current,
  className,
  children,
}: NavbarItemProps) {
  const classNames = cx("ns-navbar__item", className);
  const currentMark = current ? { "aria-current": "page" as const } : {};

  if (href) {
    return (
      <li>
        <Button variant="ghost" href={href} className={classNames} {...currentMark}>
          {children}
        </Button>
      </li>
    );
  }

  if (isValidElement<LinkChild>(children)) {
    return (
      <li>
        {cloneElement(children, {
          className: cx("ns-button", classNames, children.props.className),
          "data-variant": "ghost",
          ...currentMark,
        })}
      </li>
    );
  }

  return (
    <li>
      <span
        className={cx("ns-button", classNames)}
        data-variant="ghost"
        {...currentMark}
      >
        {children}
      </span>
    </li>
  );
}

export type NavbarSpacerProps = ComponentProps<"span">;

export function NavbarSpacer({ className, ...rest }: NavbarSpacerProps) {
  return (
    <span
      className={cx("ns-navbar__spacer", className)}
      aria-hidden="true"
      {...rest}
    />
  );
}

@layer components {
  .ns-navbar {
    display: flex;
    align-items: center;
    gap: var(--space-8, 1.19rem);
    box-sizing: border-box;
    width: 100%;
    min-height: var(
      --control,
      calc(
        var(--type-md, 1rem) * var(--leading-tight, 1.25) + var(--space-4, 0.49rem) *
          2
      )
    );
    padding: var(--space-2, 0.31rem) var(--space-5, 0.61rem);
    border: 0;
    border-bottom: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 12%, transparent));
    background: var(--bg, #fff);
    box-shadow: none;
    color: var(--text-body, #444);
  }

  .ns-navbar__brand {
    flex-shrink: 0;
    color: var(--text-heading, #111);
    font-weight: var(--weight-medium, 500);
    line-height: var(--leading-tight, 1.25);
    text-decoration: none;
  }

  .ns-navbar__brand:hover {
    color: var(--text-heading, #111);
  }

  .ns-navbar__menu {
    display: flex;
    align-items: center;
    min-width: 0;
  }

  .ns-navbar__menu::details-content {
    display: contents;
    content-visibility: visible;
  }

  .ns-button.ns-navbar__toggle {
    display: none;
    list-style: none;
  }

  .ns-navbar__toggle::-webkit-details-marker,
  .ns-navbar__toggle::marker {
    display: none;
    content: "";
  }

  .ns-navbar__list {
    display: flex;
    align-items: center;
    gap: var(--space-1, 0.25rem);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ns-button.ns-navbar__item,
  .ns-navbar__item {
    min-height: calc(
      var(--type-sm, 0.8rem) * var(--leading-tight, 1.25) + var(--space-2, 0.31rem) *
        2
    );
    padding-block: var(--space-1, 0.25rem);
    padding-inline: var(--space-4, 0.49rem);
    font-size: var(--type-sm, 0.8rem);
    color: var(--text-sub, #5c5c5c);
  }

  .ns-button.ns-navbar__item[aria-current="page"] {
    color: var(--text-heading, #111);
    border-color: transparent;
    background: var(--bg-hover, #f3f2f1);
    box-shadow: var(--flat);
  }

  .ns-navbar__spacer {
    flex: 1 1 auto;
    min-width: var(--space-4, 0.49rem);
  }

  @media (hover: hover) {
    .ns-navbar__item:hover:not(:disabled):not([aria-disabled="true"]) {
      color: var(--text-heading, #111);
    }

    .ns-button.ns-navbar__item[aria-current="page"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ) {
      color: var(--text-heading, #111);
      border-color: transparent;
      background: var(--bg-hover, #f3f2f1);
      box-shadow: var(--flat);
    }
  }

  @media (max-width: 48rem) { /* --bp-md */
    .ns-navbar__menu {
      position: relative;
    }

    .ns-navbar__menu::details-content {
      display: block;
      content-visibility: hidden;
    }

    .ns-navbar__menu[open]::details-content {
      content-visibility: visible;
    }

    .ns-button.ns-navbar__toggle {
      display: inline-flex;
    }

    .ns-navbar__list {
      display: none;
    }

    .ns-navbar__menu[open] .ns-navbar__list {
      display: flex;
      flex-direction: column;
      align-items: stretch;
      position: absolute;
      top: calc(100% + var(--space-2, 0.31rem));
      inset-inline-start: 0;
      z-index: var(--z-nav, 10);
      min-width: 10rem;
      padding: var(--inset-list, var(--space-2, 0.31rem));
      border: 1px solid var(--face-line, #626262);
      border-radius: var(
        --radius-list,
        calc(var(--radius, 0.4rem) + var(--space-2, 0.31rem))
      );
      background: var(--face);
      background-clip: padding-box;
      box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
    }

    .ns-navbar__menu[open] .ns-navbar__item {
      width: 100%;
      justify-content: flex-start;
    }
  }
}

.ns-navbar a {
  text-decoration: none;
}

.ns-navbar a.ns-navbar__item {
  color: var(--text-sub, #5c5c5c);
}

.ns-navbar a.ns-navbar__brand {
  color: var(--text-heading, #111);
}

.ns-navbar a.ns-navbar__item[aria-current="page"] {
  color: var(--text-heading, #111);
}

@media (hover: hover) {
  .ns-navbar a.ns-navbar__item:hover {
    color: var(--text-heading, #111);
  }

  .ns-navbar a.ns-navbar__item[aria-current="page"]:hover {
    color: var(--text-heading, #111);
  }
}
